KG42.register("clusters-f80394833be6aabf8edf46ef",{"id":"25-p2p_ancillary_bidding::v142-d-CL006","paper":"25-p2p_ancillary_bidding","label":"Ancillary service signal publication, quota procurement, and existing agreement fee adjustment","record":{"cluster_id":"v142-d-CL006","label":"Ancillary service signal publication, quota procurement, and existing agreement fee adjustment","market_meaning":"The utility publishes the service demand, type, and fixed price and allocates procurement quotas based on customer submitted quantities; the final procurement quantity is used for remuneration calculation, and changes to existing P2P or P2G agreements caused by the service are handled according to their respective conditions for compensation, penalty exemption, and electricity charge changes. The existing quantitative fee analysis mainly covers Type-1 services.","mechanism_ids":["v141-a-M03-ancillary-service","v141-a-M01-p2p-cda","v141-a-M02-residual-balancing"],"market_types":["LEM","LEM_DEM"],"process_stages":["clearing","coordination","settlement","pricing"],"scope_disposition":"conditional","scope_explanation":"M03 publishes demand and procures services; M01 and M02 provide only the price and obligation interfaces of existing agreements. Retain the original LEM labels of R014/R015 and the LEM_DEM label of R016. The correspondence between procurement quota and remuneration quantity is limited to the final determined Type-1 quantity, and intermediate quotas or Type-2 situations cannot be directly substituted; settlement here refers to the forward agreement fee arrangement and is not extended to real-time settlement under uncertainty.","assembly_status":"partial","boundary_rationale":"Demand parameters enter quota allocation, the final quantity and fixed service price enter remuneration, and existing agreements enter fee adjustment, constituting a procurement candidate with actual information interfaces. A chain for customer optimized bidding is still missing, and the narrative order from publication to procurement cannot replace the customer's decision; the utility's optimization method for generating demand and prices remains outside the scope according to the source.","chain_bindings":[{"chain_id":"v141-c-R014","ownership":"primary","role":"core","rationale":"Carry the allocation procedure from submitted quantities to procurement quotas and the customer's final selection, with its mathematical issues kept explicit."},{"chain_id":"v141-c-R015","ownership":"primary","role":"core","rationale":"Provide the service demand, fixed price, type, and publication responsibility as exogenous inputs to procurement and remuneration."},{"chain_id":"v141-c-R016","ownership":"primary","role":"core","rationale":"Carry the final procurement remuneration and the agreement fee adjustments caused by the service, retaining the conditions of each branch."},{"chain_id":"v141-c-R009","ownership":"shared","role":"interface","rationale":"Provide the source of existing P2P execution prices; the correspondence of specific agreement identifiers still needs to be supplemented."},{"chain_id":"v141-c-R011","ownership":"shared","role":"interface","rationale":"Provide the context of the original P2G electricity supply and purchase obligation so that the avoided original electricity charge and the newly added ancillary service arrangement remain distinguishable."}],"connections":[{"connection_id":"v142-d-CL006-CON01","from_chain_id":"v141-c-R015","to_chain_id":"v141-c-R014","kind":"quantity_interface","from_refs":["v141-c-R015::theta::theta-DAS"],"to_refs":["v141-c-R014::theta::v141-c-R014-p-D"],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E12-fig3-quota-algorithm"],"rationale":"The service demand published for the same target time slot enters the initialization of the quota algorithm; the service type must correspond to the same procurement."},{"connection_id":"v142-d-CL006-CON02","from_chain_id":"v141-c-R014","to_chain_id":"v141-c-R016","kind":"quantity_interface","from_refs":["v141-c-R014::x::v141-c-R014-v-q","v141-c-R014::phi::v141-c-R014-C003","v141-c-R014::phi::v141-c-R014-C004"],"to_refs":["v141-c-R016::x::v141-c-R016-x-q-it","v141-c-R016::phi::v141-c-R016-C001"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm","v141-b-g02-E15-eq23-as-reward"],"rationale":"The remuneration source explicitly adopts the procurement quantity determined in Fig. 3; this corresponds to the final Type-1 procurement quantity after Step III, not to an interim quota in the iteration."},{"connection_id":"v142-d-CL006-CON03","from_chain_id":"v141-c-R015","to_chain_id":"v141-c-R016","kind":"quantity_interface","from_refs":["v141-c-R015::theta::theta-pAS","v141-c-R015::phi::v141-c-R015-C002"],"to_refs":["v141-c-R016::theta::v141-c-R016-theta-pAS-t","v141-c-R016::phi::v141-c-R016-C001"],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E10-as-step2-bid-form-eq17","v141-b-g02-E15-eq23-as-reward"],"rationale":"The same service price published and fixed by the utility enters the procurement remuneration calculation; it is not equivalent to the P2P execution price."},{"connection_id":"v142-d-CL006-CON04","from_chain_id":"v141-c-R009","to_chain_id":"v141-c-R016","kind":"quantity_interface","from_refs":["v141-c-R009::x::v141-c-R009-x-pi-t"],"to_refs":["v141-c-R016::theta::v141-c-R016-theta-pi-gt","v141-c-R016::phi::v141-c-R016-C002"],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E11","v141-b-g01-E17","v141-b-g02-E22-eq32-penalty-cost","v141-b-g02-E23-eq33-avoided-p2p-cost-benefit"],"rationale":"The fee adjustment reads the execution price stored in the affected P2P agreement. The interface holds only when it is confirmed that the specific execution corresponds to agreement g; currently, no unconditional same-value mapping is established between all time-slot execution prices and agreement prices."},{"connection_id":"v142-d-CL006-CON05","from_chain_id":"v141-c-R011","to_chain_id":"v141-c-R016","kind":"functional_coupling","from_refs":["v141-c-R011::phi::v141-c-R011-C001"],"to_refs":["v141-c-R016::phi::v141-c-R016-C006","v141-c-R016::phi::v141-c-R016-C007"],"evidence_ids":["v141-b-g01-E20","v141-b-g02-E19-eq29-demand-reduction-parts","v141-b-g02-E20-eq30-p2g-reduction-benefit","v141-b-g02-E14-table1-adjustments"],"rationale":"Under a positive baseline, reducing demand originally supplied by the utility avoids the original P2G electricity charge and applies the penalty-exemption arrangement in the ancillary service adjustment; the original supply obligation and the subsequent penalty-exemption rule retain different mechanism attributions."}],"object_mappings":[{"mapping_id":"v142-d-CL006-OM01","kind":"same_quantity","member_refs":["v141-c-R015::theta::theta-DAS","v141-c-R014::theta::v141-c-R014-p-D"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E12-fig3-quota-algorithm"],"rationale":"The demand parameters of the same service procurement and the same time slot are used respectively for publication and quota initialization, and the local uses remain independent."},{"mapping_id":"v142-d-CL006-OM02","kind":"same_quantity","member_refs":["v141-c-R015::theta::theta-pAS","v141-c-R016::theta::v141-c-R016-theta-pAS-t"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E10-as-step2-bid-form-eq17","v141-b-g02-E15-eq23-as-reward"],"rationale":"The fixed publication price in the same time slot and service procurement is read by the remuneration formula; the roles of the publication parameter and the fee-calculation parameter are retained, and the unit issue is disclosed separately."},{"mapping_id":"v142-d-CL006-OM03","kind":"same_quantity","member_refs":["v141-c-R014::x::v141-c-R014-v-q","v141-c-R016::x::v141-c-R016-x-q-it"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm","v141-b-g02-E15-eq23-as-reward"],"rationale":"It corresponds to the procured service quantity of R016 only when R014 completes the final selection and the procurement is Type-1; the iterative quota state of R014 is not merged with this payment input."},{"mapping_id":"v142-d-CL006-OM04","kind":"same_node","member_refs":["v141-c-R014::V::coordination.local_operator","v141-c-R015::V::coordination.local_operator"],"canonical_ref":"v141-c-R015::V::coordination.local_operator","display_policy":"single_representative","evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E11-as-step3-fairness"],"rationale":"In both places, the utility in the same ancillary service procurement bears the publication and procurement coordination responsibilities; it is not directly equated with the role of the same name in the CDA exchange."},{"mapping_id":"v142-d-CL006-OM05","kind":"same_node","member_refs":["v141-c-R014::V::clearing.local","v141-c-R016::V::clearing.local"],"canonical_ref":"v141-c-R014::V::clearing.local","display_policy":"single_representative","evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm","v141-b-g02-E15-eq23-as-reward"],"rationale":"In the Type-1 fee branch, the allocation function referenced by remuneration is the Fig. 3 procurement quota function; it is not expanded to the electrical energy execution clearing of M01."}],"gaps":[{"gap_id":"v142-d-CL006-G01","category":"upstream_missing","description":"There is currently no Rule-Chain carrying the optimization of customer ancillary service bids, so it is impossible to connect the fixed signal, the original submitted quantity, and the final selection under the quota constraint. The source presents two optimization processes, but R015 cannot be directly jumped to as an already expressed customer decision.","chain_ids":["v141-c-R014","v141-c-R015","v141-c-R016"],"object_refs":["v141-c-R014::theta::v141-c-R014-p-b","v141-c-R014::phi::v141-c-R014-C004","v141-c-R015::phi::v141-c-R015-C002"],"evidence_ids":["v141-b-g02-E10-as-step2-bid-form-eq17","v141-b-g02-E27-eq36-objective","v141-b-g02-E28-eq37-bid-netload-relation","v141-b-g02-E29-eq38-quota-bound","v141-b-g02-E30-optimization-definitions","v141-b-g02-E32-two-run-quota-process"],"proposal_ids":[],"required_work":"Upstream should establish referable customer optimization and two-bid chains, distinguishing the original bid, the allocated quota, and the final procurement selection; D does not supply missing formulas or decision nodes."},{"gap_id":"v142-d-CL006-G02","category":"math_incomplete","description":"R014 repeatedly accumulates quotas according to the existing transcription but truncates excess customers only at Step III; old excess may again be counted in subsequent Q_t and be repeatedly allocated, and on this basis it cannot be confirmed that the total procurement quantity is constrained by demand. Step I lacks an explicit pre-division safeguard when the demand set is empty; and after the final customer actively reduces its quantity, there is no procedure to fill the shortfall.","chain_ids":["v141-c-R014"],"object_refs":["v141-c-R014::phi::v141-c-R014-C002","v141-c-R014::phi::v141-c-R014-C003","v141-c-R014::phi::v141-c-R014-C004","v141-c-R014::phi::v141-c-R014-C007","v141-c-R014::phi::v141-c-R014-C008","v141-c-R014::phi::v141-c-R014-C009","v141-c-R014::phi::v141-c-R014-C010"],"evidence_ids":["v141-b-g02-E11-as-step3-fairness","v141-b-g02-E12-fig3-quota-algorithm"],"proposal_ids":[],"required_work":"Verify the original text of Fig. 3 and the state updates, and check the excess clawback, set recomputation, empty-set, and final-shortfall cases; any correction must be explicitly proposed by upstream, and it cannot currently be claimed that the algorithm guarantees conservation, a total quantity cap, or demand satisfaction."},{"gap_id":"v142-d-CL006-G03","category":"math_incomplete","description":"The service price is labeled £/kW/h, whereas Eq. (23) only multiplies this price by the procured power; when interpreted together with electrical energy amounts that include duration, the time basis of the hourly revenue and the time-slot amount has not been closed.","chain_ids":["v141-c-R015","v141-c-R016"],"object_refs":["v141-c-R015::theta::theta-pAS","v141-c-R016::theta::v141-c-R016-theta-pAS-t","v141-c-R016::phi::v141-c-R016-C001","v141-c-R016::theta::v141-c-R016-theta-Delta-t"],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E15-eq23-as-reward","v141-b-g02-E16-eq24-export-benefit","v141-b-g02-E24-eq34-total-benefit"],"proposal_ids":[],"required_work":"Verify the price unit, the remuneration measurement period, and the revenue aggregation basis; do not independently add multiplication by duration, assume a unit duration, or rewrite the source formula."},{"gap_id":"v142-d-CL006-G04","category":"math_incomplete","description":"Although R016 references multiple service components, it does not include the complete decomposition constraints of Eq. (25) to (27), (29), and (31) or the total cost-revenue closure. The transcription of the provided total revenue also uses different apostrophes for the P2G component, and their identities cannot be silently unified.","chain_ids":["v141-c-R016"],"object_refs":["v141-c-R016::x::v141-c-R016-x-q-it","v141-c-R016::x::v141-c-R016-x-qdouble-it","v141-c-R016::x::v141-c-R016-x-qprime-I-it","v141-c-R016::x::v141-c-R016-x-qprime-I-itg","v141-c-R016::x::v141-c-R016-x-qdoubleprime-II-it"],"evidence_ids":["v141-b-g02-E17-eq25-27-decomposition","v141-b-g02-E19-eq29-demand-reduction-parts","v141-b-g02-E21-eq31-p2p-award-allocation","v141-b-g02-E24-eq34-total-benefit","v141-b-g02-E25-eq35-total-cost","v141-b-g03-e002"],"proposal_ids":[],"required_work":"Upstream should verify the component notation, decomposition relations, and applicable conditions, and supplement the necessary referable constraints; retain the existing objects and symbols, and do not treat the components as a complete payment model that can take arbitrary independent values."},{"gap_id":"v142-d-CL006-G05","category":"scope_conflict","description":"The qualitative arrangement in Table 1 of R016 includes different service change directions, but the quantitative compensation and avoided-expenditure formulas cover only specific Type-1 and baseline branches. C002 and C005 share the compensation term rather than duplicating the entire item, so the entire rule cannot be deduplicated, and the common compensation cannot be repeatedly accumulated. The detailed fee analysis for Type-2 is explicitly omitted in the source.","chain_ids":["v141-c-R016"],"object_refs":["v141-c-R016::phi::v141-c-R016-C002","v141-c-R016::phi::v141-c-R016-C004","v141-c-R016::phi::v141-c-R016-C005","v141-c-R016::phi::v141-c-R016-C006","v141-c-R016::phi::v141-c-R016-C007"],"evidence_ids":["v141-b-g02-E14-table1-adjustments","v141-b-g02-E20-eq30-p2g-reduction-benefit","v141-b-g02-E22-eq32-penalty-cost","v141-b-g02-E23-eq33-avoided-p2p-cost-benefit","v141-b-g02-E26-type2-omitted"],"proposal_ids":[],"required_work":"Manually confirm the branch boundaries and duplicate-item display of the qualitative principles and Type-1 formulas; keep the Type-2 omission explicit and do not write an analogical derivation as a formula already present in the source. The textual P2G penalty-exemption obligation continues to be retained, with no need to fabricate a zero-penalty formula."},{"gap_id":"v142-d-CL006-G06","category":"ambiguous_mapping","description":"R009 records a matching price by time slot, and R016 reads the historical agreement price according to agreement g; there is currently no referable object that completely associates the execution event, the two trading parties, agreement g, and the corresponding reduced share.","chain_ids":["v141-c-R009","v141-c-R016"],"object_refs":["v141-c-R009::x::v141-c-R009-x-pi-t","v141-c-R016::theta::v141-c-R016-theta-pi-gt","v141-c-R016::x::v141-c-R016-x-qprime-I-itg"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E17","v141-b-g02-E21-eq31-p2p-award-allocation","v141-b-g02-E22-eq32-penalty-cost"],"proposal_ids":[],"required_work":"Upstream should clarify the agreement identity, execution-price storage, and correspondence of the affected share; until then, keep the conditional quantity interface and do not select a cross-mechanism price representative."},{"gap_id":"v142-d-CL006-G07","category":"ontology_extension","description":"The dedicated node proposals for ancillary service products, service quotas, and reward-penalty pricing remain pending. The currently borrowed coordination, clearing, and payment nodes do not mean that these extensions have been approved, nor do they make ancillary services and local electrical energy the same product.","chain_ids":["v141-c-R014","v141-c-R015","v141-c-R016"],"object_refs":["v141-c-R014::V::clearing.local","v141-c-R015::V::coordination.price_signal","v141-c-R016::V::settlement.payment"],"evidence_ids":["v141-b-g02-E08-as-categories","v141-b-g02-E09-as-step1-publication","v141-b-g02-E11-as-step3-fairness","v141-b-g02-E12-fig3-quota-algorithm","v141-b-g02-E15-eq23-as-reward","v141-b-g02-E22-eq32-penalty-cost"],"proposal_ids":["v141-b-g01-P01","v141-b-g02-P01-ancillary-service-product","v141-b-g03-prop-ancillary-service-product","v141-b-g02-P02-service-quota-allocation","v141-b-g03-prop-ancillary-quota-allocation","v141-b-g02-P03-ancillary-service-pricing"],"required_work":"Manually check the relevant proposals and the applicable boundaries of existing nodes; continue to retain the frozen objects and do not insert or approve ontology extensions at the D layer."},{"gap_id":"v142-d-CL006-G08","category":"unverified_source","description":"The signal, quota algorithm, fee formulas, and cross-mechanism agreement interfaces are all supported only by currently unreviewed B evidence; this time no B source audit, C2 independent review, or Agent E review was conducted.","chain_ids":["v141-c-R014","v141-c-R015","v141-c-R016","v141-c-R009","v141-c-R011"],"object_refs":[],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E20","v141-b-g01-E25","v141-b-g02-E09-as-step1-publication","v141-b-g02-E12-fig3-quota-algorithm","v141-b-g02-E15-eq23-as-reward","v141-b-g02-E22-eq32-penalty-cost","v141-b-g02-E23-eq33-avoided-p2p-cost-benefit"],"proposal_ids":[],"required_work":"Subsequent manual verification of sources, branches, dimensions, algorithm status, and protocol identity; experimental support eligibility or this assembly must not be interpreted as scientific acceptance."}]},"rule_refs":["25-p2p_ancillary_bidding::v141-c-R014","25-p2p_ancillary_bidding::v141-c-R015","25-p2p_ancillary_bidding::v141-c-R016","25-p2p_ancillary_bidding::v141-c-R009","25-p2p_ancillary_bidding::v141-c-R011"],"unresolved_rule_refs":[],"node_ids":["COMP-464efdadf92efbd8","COMP-58e2723fe0b22957","COMP-739917e3869e45a6","COMP-7463d1518c82517a","COMP-820a6d5bf777024c","COMP-d5bf3c5421ae2369","KG31-69ba805a251afd65","KG40-12aedc3eec573697","KG40-20f45ec4bdcbac06"]});
